def mark():
 return '<svg class="rose-mark" viewBox="0 0 44 44" aria-hidden="true"><path d="M22 3c10 0 18 8 18 18S32 39 22 39 4 31 4 21 12 3 22 3Zm0 8c-6 0-11 4-11 10s5 10 11 10 10-4 10-10-6-8-10-8-7 3-7 7 3 6 7 6 5-2 5-5"/><path d="M22 39v4M22 4V0M4 21H0m40 0h4"/></svg>'
nav=[('index.html','Home'),('works.html','The Works'),('about.html','About Remy'),('rguytano.html','RGuytano™'),('journal.html','Journal'),('contact.html','Contact')]
def layout(title,body,page='index.html',prefix='',desc=None):
 description=desc or 'The literary home of R Remy Miller. Novels, poetry, essays, short fiction, and the art and music of RGuytano. Many Worlds. One Imagination.'
 navigation=''.join(f'<a href="{prefix}{p}"'+(' aria-current="page"' if p==page else '')+f'>{label}</a>' for p,label in nav)
 return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#19151a"><title>{E(title)} | R Remy Miller</title><meta name="description" content="{E(description,quote=True)}"><meta property="og:title" content="{E(title,quote=True)} | R Remy Miller"><meta property="og:description" content="{E(description,quote=True)}"><meta property="og:type" content="website"><meta property="og:image" content="{prefix}assets/christmas-library.jpg"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="{prefix}assets/favicon.svg" type="image/svg+xml"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,500;0,600;1,400;1,500&family=DM+Sans:wght@400;500;600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="{prefix}assets/style.css"><script src="{prefix}assets/site.js" defer></script></head>
<body><a class="skip-link" href="#main">Skip to content</a><header class="header"><div class="header-inner"><a class="brand" href="{prefix}index.html" aria-label="R Remy Miller home">{mark()}<span>R REMY MILLER<small>THE LITERARY ATELIER</small></span></a><button class="menu-toggle" aria-label="Open navigation" aria-expanded="false" aria-controls="main-nav">Menu <span>☰</span></button><nav id="main-nav" aria-label="Main navigation">{navigation}</nav></div></header>
<main id="main">{body}</main>
<div class="top-band" hidden><a class="top-link" href="#top">↑ Top of page</a></div><footer class="pair-footer pair-host-remy"><p class="pair-eyebrow">Spiral Empire Enterprises</p><div class="pair-band"><a class="pair-door pair-door-remy" href="https://rremymiller.com/"><img src="{prefix}assets/remy-spiral-logo.png" alt="R Remy Miller"><span class="pair-door-text"><span class="pair-door-name">R Remy Miller</span><span class="pair-door-desc">The Literary Atelier, words</span><span class="pair-door-state lbl-visit">Visit the atelier →</span><span class="pair-door-state lbl-home">You are here</span></span></a><div class="pair-join"><span class="diamond"></span></div><a class="pair-door pair-door-rg" href="https://rguytano.com/"><img src="{prefix}assets/rguytano-rg-logo.png" alt="RGuytano"><span class="pair-door-text"><span class="pair-door-name">RGuytano</span><span class="pair-door-desc">Art &amp; Music</span><span class="pair-door-state lbl-visit">Visit the gallery →</span><span class="pair-door-state lbl-home">You are here</span></span></a></div><nav class="pair-family" aria-label="Web Mastering by Horizon Technologys"><a href="https://horizontks.com/" title="Horizon Technologys"><img src="{prefix}assets/horizon-logo-2026.png" alt="Horizon Technologys" height="40"></a><a class="pair-markham" href="https://markhamideas.org/" title="Markham" aria-label="Markham"><span class="pair-markham-word" aria-hidden="true">M<span class="pair-markham-dot">.</span></span></a><a href="https://theryehouse.com/" title="The Rye House"><img src="{prefix}assets/rye-tree-clean.png" alt="The Rye House" height="40"></a><a href="https://remy1miller.substack.com/" title="Substack: Welcome to my Neighborhood"><img src="{prefix}assets/substack-glyph.png" alt="Substack" height="40"></a></nav><p class="pair-credit">Web Mastering by Horizon Technologys</p><p class="pair-copy">© Robert Eugene Miller. All Rights Reserved</p></footer>
</body></html>'''

def art(w):
 return f'<div class="book-art {w["art"]}" aria-hidden="true"><span class="book-series">R REMY MILLER</span><i class="book-symbol"></i><span class="book-title">{E(w["title"])}</span><span class="book-subtitle">{E(w["subtitle"])}</span></div>'
def bookcard(w,prefix='',featured=False):
 return f'<article class="work-card" data-category="{E(w["category"])}" data-search="{E((w["title"]+" "+w["subtitle"]+" "+w["category"]).lower(),quote=True)}"><a class="book-link" href="{prefix}works/{w["id"]}.html">{art(w)}<div class="work-meta"><span>{E(w["category"])}</span><span class="arrow" aria-hidden="true">↗</span></div><h3>{E(w["title"])}</h3></a><p class="work-summary">{E(w["description"] if featured else w["subtitle"])}</p><span class="status">{E(w["status"])}</span></article>'

home='''<section class="hero"><div class="hero-copy"><p class="eyebrow"><span class="gold-dot"></span> THE LITERARY ATELIER</p><h1>Many Worlds.<br><em>One Imagination.</em></h1><p class="hero-intro">Stories of mystery, wonder, love, consciousness, and the extraordinary possibilities of being.</p><a class="button button-gold" href="works.html">Enter the worlds <span aria-hidden="true">↗</span></a><p class="hero-footnote">NOVELIST · POET · STORYTELLER · ARTIST</p></div><figure class="hero-image"><img src="assets/christmas-library.jpg" width="626" height="626" alt="A welcoming Christmas library with a glowing fireplace, a tree dressed in gold and crimson, and an armchair beside the bookshelves" fetchpriority="high"><figcaption><span>CHRISTMAS AT THE ATELIER</span>A place for stories.<br><em>A little room for wonder.</em></figcaption><span class="image-corner" aria-hidden="true">✦</span></figure></section>
<div class="genre-ribbon" aria-label="Literary forms"><span>FICTION</span><b>✦</b><span>POETRY</span><b>✦</b><span>PHILOSOPHY</span><b>✦</b><span>WONDER</span><b>✦</b><span>ART &amp; MUSIC</span></div>
<section class="section feature-section"><div class="section-heading"><div><p class="eyebrow">A FEW DOORS TO BEGIN WITH</p><h2>Step into a different world.</h2></div><a class="text-link" href="works.html">Explore the catalogue <span aria-hidden="true">↗</span></a></div><div class="book-grid featured-grid">'''+''.join(bookcard(w,featured=True) for w in catalogue[:3])+'''</div></section>
<section class="author-note section"><div class="note-number" aria-hidden="true">R<span>R</span>M</div><div><p class="eyebrow">THE IMAGINATION BEHIND THE WORLDS</p><h2>A life made of<br><em>curiosity and creation.</em></h2><p>From mythic landscapes and gothic mysteries to poetry, philosophical conversation, and children’s wonder, R Remy Miller follows the questions that refuse to sit quietly.</p><p>Different forms. A shared fascination with who we are, what we perceive, and how much more a life might hold.</p><a class="text-link" href="about.html">Meet Remy <span aria-hidden="true">↗</span></a></div></section>
<section class="art-invitation section"><div><p class="eyebrow">ANOTHER EXPRESSION OF THE IMAGINATION</p><h2>RGuytano<sup>™</sup></h2><p>Where the story becomes color.<br>Where the imagination becomes sound.</p><a class="text-link" href="rguytano.html">Discover the artist <span aria-hidden="true">↗</span></a></div><div class="orb-composition"><img src="assets/rguytano-emblem.png" alt="The RGuytano emblem" style="height:100%;width:auto;max-width:100%;object-fit:contain;box-shadow:14px 16px 0 rgba(0,0,0,.18)"></div></section>
<section class="welcome section"><p class="eyebrow">A SEASON FOR STORIES</p><h2>Come in. There is<br><em>room by the fire.</em></h2><p>For a story, a question, a little laughter.<br>For something that reminds us how much there is still to discover.</p><a class="button button-outline" href="https://remy1miller.substack.com/">A little more reading <span aria-hidden="true">↗</span></a></section>'''
(ROOT/'index.html').write_text(layout('Many Worlds. One Imagination.',home))

categories=['All works']+list(dict.fromkeys(w['category'] for w in catalogue))
filterbuttons=''.join(f'<button type="button" class="filter-button'+(' active' if i==0 else '')+f'" data-filter="{E(c)}" aria-pressed="'+('true' if i==0 else 'false')+f'">{E(c)}</button>' for i,c in enumerate(categories))
body='''<section class="page-heading section"><p class="eyebrow">THE CATALOGUE</p><h1>The Works<span class="gold-period">.</span></h1><p class="page-deck">Every world begins with an invitation.<br>Find the one that calls to you.</p></section><section class="section catalogue-section"><div class="catalogue-tools"><div class="filters" aria-label="Filter the catalogue">'''+filterbuttons+'''</div><label class="search-label"><span class="sr-only">Search the works</span><input id="work-search" type="search" placeholder="Find a title or a world…" autocomplete="off"><span aria-hidden="true">⌕</span></label></div><div class="catalogue-caption"><p id="result-count" aria-live="polite">'''+str(len(catalogue))+''' works to explore</p><p>Published writing &amp; works taking shape</p></div><div class="book-grid catalogue-grid" id="catalogue-grid">'''+''.join(bookcard(w) for w in catalogue)+'''</div><p id="no-results" class="empty-results" hidden>No works match that search. Try another title or choose All works.</p><p class="catalogue-note">The catalogue brings together named works, published episodes, and developing projects. Availability is shown on each entry; inclusion does not indicate publication.</p></section>'''
(ROOT/'works.html').write_text(layout('The Works',body,'works.html'))

body='''<section class="about-hero section"><div><p class="eyebrow">THE AUTHOR</p><h1>Curiosity.<br>Imagination.<br><em>A little mischief.</em></h1></div><figure class="portrait"><img src="assets/remy-library-portrait.png" alt="R Remy Miller in a burgundy jacket, resting his cheek on his hand in a warmly lit library" width="1111" height="1416"><figcaption>R REMY MILLER · AUTHOR &amp; MULTIMEDIA CREATOR</figcaption></figure></section><section class="section biography"><p class="eyebrow">ABOUT REMY</p><div><h2>The extraordinary possibilities<br><em>of being.</em></h2><p class="large-copy">I write across worlds: literary and speculative fiction, poetry, philosophy, children’s stories, and the occasional outbreak of comic disorder.</p><p>Underneath the different forms is a continuing curiosity about consciousness, identity, love, memory, and what becomes possible when we make room for imagination.</p><p>My journey has included the U.S. Coast Guard, studies in communications and philosophy at Northern Illinois University, and a lifelong interest in phenomenology, action theory, and cosmology. These threads find their way into the stories, questions, images, and music.</p><p>R Remy Miller is my literary home. RGuytano™ is the name under which I explore visual art and music. Spiral Empire Enterprises™ brings these creative expressions together.</p><a class="text-link" href="works.html">Find your next world <span aria-hidden="true">↗</span></a></div></section><section class="values section"><p class="eyebrow">A FEW THINGS WORTH KEEPING</p><div><h3>Stories can open doors.</h3><h3>Curiosity deserves room.</h3><h3>Compassion belongs in the work.</h3><h3><em>And humor is non-negotiable.</em></h3></div></section>'''
(ROOT/'about.html').write_text(layout('About Remy',body,'about.html'))

body='''<section class="artist-hero section"><p class="eyebrow">ART · MUSIC · ANOTHER WAY OF SEEING</p><h1>RGuytano<sup>™</sup></h1><p class="artist-statement">The story beyond <em>the word.</em></p><div class="artist-rule" aria-hidden="true"><span></span>✦<span></span></div><p class="page-deck">The visual and musical expression of the imagination<br>behind R Remy Miller.</p></section><section class="artist-content section"><div class="orb-composition large-orb"><img src="assets/rguytano-emblem.png" alt="The RGuytano emblem" style="height:100%;width:auto;max-width:100%;object-fit:contain"></div><div><p class="eyebrow">MEET THE ARTIST</p><h2>Some worlds are seen.<br><em>Some are heard.</em></h2><p>RGuytano™ works in digital visual art and electronic music, exploring the surreal, the symbolic, and the atmospheric. It is a distinct expression of the same curiosity that moves through the literary work.</p><p>Here, the imagination has room to speak in color, composition, texture, and sound.</p><p class="artist-future">An independent home for the art and music is taking shape at <strong>RGuytano.com</strong>. This page will become the doorway to that world when it opens.</p><a class="text-link" href="contact.html">Art &amp; music enquiries <span aria-hidden="true">↗</span></a></div></section><section class="section artist-forms"><article><span>01 / VISUAL</span><h2>Art as an encounter.</h2><p>Digital works and visual storytelling. An invitation to look again, and perhaps see a little differently.</p></article><article><span>02 / MUSICAL</span><h2>Imagination in sound.</h2><p>Electronic composition and musical exploration, where atmosphere and feeling can lead the story.</p></article></section>'''
gallery = '<section class="section artist-gallery"><div class="section-heading"><div><p class="eyebrow">A GLIMPSE OF THE VISUAL WORLD</p><h2>Color. Light. Imagination.</h2></div><a class="text-link" href="https://opensea.io/rguytano">Explore the digital collections <span aria-hidden="true">↗</span></a></div><div class="gallery-grid">'
for number,view,label in [('01','658 94 152 111','Luminous blue forms and musical movement'),('02','819 155 140 140','Abstract digital art in gold and amber'),('03','872 305 149 150','A colorful digital ape portrait')]:
 gallery += f'<figure><svg viewBox="{view}" preserveAspectRatio="xMidYMid slice" role="img" aria-label="{label}"><image href="assets/rguytano-world.png" width="1050" height="812"/></svg><figcaption><span>RGuytano™</span>SELECTED DIGITAL WORK / {number}</figcaption></figure>'
gallery += '</div></section>'
body=body.replace('<section class="section artist-forms">',gallery+'<section class="section artist-forms">')
(ROOT/'rguytano.html').write_text(layout('RGuytano: Art & Music',body,'rguytano.html'))

body='''<section class="page-heading section"><p class="eyebrow">NOTES FROM THE ATELIER</p><h1>The Journal<span class="gold-period">.</span></h1><p class="page-deck">Writing, questions, discoveries.<br>And the occasional delightful interruption.</p></section><section class="journal-grid section"><article class="journal-feature"><img src="assets/christmas-library.jpg" width="626" height="626" alt="Christmas warmth in the Literary Atelier" loading="lazy"><div><p class="eyebrow">NOVEMBER 2026 · FROM THE ATELIER</p><h2>A season for<br><em>new beginnings.</em></h2><p>The Literary Atelier brings the worlds of R Remy Miller together: stories, poetry, philosophical conversations, and the art and music of RGuytano. A new home for a continuing creative life.</p><a class="text-link" href="works.html">Explore the worlds <span aria-hidden="true">↗</span></a></div></article><article class="journal-follow"><p class="eyebrow">THE ONGOING CONVERSATION</p><h2>More words.<br><em>More possibilities.</em></h2><p>For current stories, poems, essays, and reflections, visit R Remy Miller on Substack.</p><a class="button button-outline" href="https://remy1miller.substack.com/">Read on Substack <span aria-hidden="true">↗</span></a></article></section>'''
(ROOT/'journal.html').write_text(layout('The Journal',body,'journal.html'))

body='''<section class="page-heading section"><p class="eyebrow">LET’S BEGIN A CONVERSATION</p><h1>A word<br><em>between worlds.</em></h1><p class="page-deck">Literary representation, publishing, creative collaboration,<br>or simply something worth sharing.</p></section><section class="contact-grid section"><div class="contact-main"><p class="eyebrow">WRITE TO REMY</p><a class="email-link" href="mailto:RRemyMiller@outlook.com">RRemyMiller@outlook.com <span aria-hidden="true">↗</span></a><p>A good conversation is often where the next possibility begins.</p><a class="button button-gold" href="mailto:RRemyMiller@outlook.com">Send an email <span aria-hidden="true">↗</span></a></div><aside class="contact-aside"><p class="eyebrow">ELSEWHERE, STILL CREATING</p><a href="https://remy1miller.substack.com/">Substack <span>Stories, poetry &amp; reflections ↗</span></a><a href="https://www.linkedin.com/in/re-miller/">LinkedIn <span>Writing &amp; professional connections ↗</span></a><a href="https://www.facebook.com/RemyRMiller">Facebook <span>Notes from a creative life ↗</span></a><a href="rguytano.html">RGuytano™ <span>Visual art &amp; music ↗</span></a></aside></section>'''
(ROOT/'contact.html').write_text(layout('Contact',body,'contact.html'))

for w in catalogue:
 external=''
 if w['id'] in links:
  wlinks=links[w['id']];wlinks=[wlinks] if isinstance(wlinks,tuple) else wlinks;external=''.join(f'<a class="button {"button-gold" if i==0 else "button-outline"}" href="{url}">{E(label)} <span aria-hidden="true">↗</span></a>' for i,(label,url) in enumerate(wlinks))
 else: external='<a class="button button-outline" href="../contact.html">Enquire about this work <span aria-hidden="true">↗</span></a>'
 body=f'''<section class="work-detail section"><div class="detail-art">{art(w)}</div><div class="detail-copy"><a class="back-link" href="../works.html">← Back to The Works</a><p class="eyebrow">{E(w['category'])}</p><h1>{E(w['title'])}</h1><p class="detail-subtitle">{E(w['subtitle'])}</p><span class="status">{E(w['status'])}</span><p class="detail-description">{E(w['description'])}</p>{external}</div></section><section class="section next-world"><p class="eyebrow">THE NEXT DOOR IS OPEN</p><h2>Stay curious.<br><em>There are other worlds.</em></h2><a class="text-link" href="../works.html">Return to the catalogue <span aria-hidden="true">↗</span></a></section>'''
 (ROOT/'works'/f'{w["id"]}.html').write_text(layout(w['title'],body,'works.html','../',w['description']))

(ROOT/'404.html').write_text(layout('A small detour','<section class="page-heading section"><p class="eyebrow">A SMALL DETOUR</p><h1>This door is<br><em>somewhere else.</em></h1><p class="page-deck">Let’s find you a world to step into.</p><a class="button button-gold" href="works.html">Explore The Works ↗</a></section>'))
(ROOT/'.nojekyll').touch()
(ROOT/'assets/favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="12" fill="#19151a"/><path d="M32 10a22 22 0 1 1-22 22c0-13 10-22 22-22m0 10a12 12 0 1 0 12 12c0-7-7-11-12-8-5 2-6 9 0 12" fill="none" stroke="#c6a16b" stroke-width="2"/></svg>')
(ROOT/'robots.txt').write_text('User-agent: *\nAllow: /\n')
print(f'Built {len(catalogue)} catalogue entries and {len(list(ROOT.glob("*.html")))+len(list((ROOT/'works').glob("*.html")))} pages')


arrow='<svg class="out-arrow" viewBox="0 0 16 16" aria-hidden="true"><path d="M3 13 13 3M3 3h10v10" fill="none" stroke="currentColor" stroke-width="1.2"/></svg>'
for page_file in [*ROOT.glob('*.html'),*(ROOT/'works').glob('*.html')]:
 page_file.write_text(page_file.read_text().replace('↗',arrow))
